// fleet-real.js — REAL ported 3D models (CC0, by Kenney / kenney.nl, obtained via the
// pmndrs/market-assets mirror; Draco-decompressed to plain glb at build time — see ASSETS.md).
// Contract: await prepare(H, GLTFLoader) once at boot (parses templates), then makeFleet(H).
const GLB = {
'ship-dark':'',
'ship-light':'',
'boat-large':'',
'boat-small':'',
'cannon':''
};
const TPL = {};   // parsed template scenes, keyed like GLB
export async function prepare(H, GLTFLoader){
  const { THREE } = H; const loader = new GLTFLoader();
  const jobs = Object.entries(GLB).map(([k, b64]) => new Promise((res) => {
    try {
      const bin = atob(b64), bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      loader.parse(bytes.buffer, '', g => {
        const box = new THREE.Box3().setFromObject(g.scene);
        TPL[k] = { scene: g.scene, size: box.getSize(new THREE.Vector3()), min: box.min.clone(), ctr: box.getCenter(new THREE.Vector3()) };
        res();
      }, e => { console.error('fleet-real parse fail', k, e); res(); });   // failed model -> procedural fallback
    } catch (e) { console.error('fleet-real decode fail', k, e); res(); }
  }));
  await Promise.all(jobs);
}
// clone a template scaled so its bow-to-stern length equals d.len, sitting on the water
function hullClone(H, key, d, sink){
  const t = TPL[key]; if (!t) return null;
  const obj = t.scene.clone(true);
  const s = d.len / Math.max(0.001, t.size.z);
  const g = new H.THREE.Group();
  obj.position.set(-t.ctr.x, 0, -t.ctr.z);
  const wrap = new H.THREE.Group(); wrap.add(obj); wrap.scale.setScalar(s);
  wrap.position.y = -(t.min.y * s) - (sink != null ? sink : d.beam * 0.22);
  g.add(wrap);
  return g;
}
function shipModel(key, sink){ return (H) => (d) => {
  const g = hullClone(H, key, d, sink); if (!g) return null;   // null -> caller keeps procedural fallback
  return H.finishShip(g, d);
}; }
export function makeFleet(H){
  const units = {
    galleon:  { name:'Galleon of the Line', cls:'GALLEON', model:'r_galleon', domain:'sea',
      len:36, beam:9, mass:1400, hp:420,
      turrets:[ {w:'mainGun', pos:[0,5.2,9],  barrel:4.6}, {w:'mainGun', pos:[0,6.4,-8], barrel:4.6}, {w:'aaGun', pos:[0,7.4,0], barrel:2.2, scale:0.9} ] },
    brig:     { name:'Brig Corsair', cls:'BRIG', domain:'sea', model:'r_brig',
      len:30, beam:8, mass:1050, hp:340,
      turrets:[ {w:'mainGun', pos:[0,4.8,7], barrel:4.2}, {w:'autocannon', pos:[0,5.6,-7], barrel:2.6} ] },
    longboat: { name:'Armed Longboat', cls:'LONGBOAT', domain:'sea', model:'r_longboat',
      len:14, beam:4, mass:45, hp:70,
      turrets:[ {w:'lightMG', pos:[0,1.6,2], barrel:1.6} ] },
    skiff2:   { name:'Skiff', cls:'SKIFF', domain:'sea', model:'r_skiff',
      len:10, beam:3, mass:28, hp:50,
      turrets:[ {w:'lightMG', pos:[0,1.4,1], barrel:1.4} ] },
    shoregun: { name:'Shore Cannon', cls:'BATTERY', domain:'land', model:'r_cannon',
      len:8, beam:4, mass:220, hp:140,
      turrets:[ {w:'mainGun', pos:[0,2.2,0], barrel:3.4} ] },
  };
  const mk = {
    r_galleon: shipModel('ship-dark'), r_brig: shipModel('ship-light'),
    r_longboat: shipModel('boat-large', 0.4), r_skiff: shipModel('boat-small', 0.3), r_cannon: shipModel('cannon', -0.1),
  };
  const models = {}; for (const k in mk) models[k] = mk[k](H);
  return { units, models };
}
